changeSet.sql:
ALTER TABLE aid_requests DROP CONSTRAINT ck_aid_requests_reservation_allowed_state, DROP CONSTRAINT ck_aid_requests_reservation_required_state, DROP CONSTRAINT ck_aid_requests_reservation_outcome_exclusive;
ALTER TABLE aid_requests ADD CONSTRAINT ck_aid_requests_reservation_allowed_state CHECK ( reservation_id IS NULL OR status IN ( 'MATCH_PENDING', 'RESERVATION_FAILED', 'RESERVED', 'DISPATCHED', 'DELIVERED', 'COMPLETED', 'CANCELLED' ) ),
ADD CONSTRAINT ck_aid_requests_reservation_required_state CHECK ( status NOT IN ( 'MATCH_PENDING', 'RESERVATION_FAILED', 'RESERVED', 'DISPATCHED', 'DELIVERED', 'COMPLETED' ) OR reservation_id IS NOT NULL ),
ADD CONSTRAINT ck_aid_requests_reservation_attempt_complete CHECK ( ( reservation_id IS NULL AND reservation_inventory_item_id IS NULL AND reservation_quantity IS NULL ) OR ( reservation_id IS NOT NULL AND reservation_inventory_item_id IS NOT NULL AND reservation_quantity IS NOT NULL AND reservation_quantity > 0 ) ),
ADD CONSTRAINT ck_aid_requests_failure_has_attempt CHECK ( reservation_failure_reason IS NULL OR reservation_id IS NOT NULL );

rollback.sql:
ALTER TABLE aid_requests DROP CONSTRAINT ck_aid_requests_reservation_attempt_complete, DROP CONSTRAINT ck_aid_requests_failure_has_attempt, DROP CONSTRAINT ck_aid_requests_reservation_allowed_state, DROP CONSTRAINT ck_aid_requests_reservation_required_state;
ALTER TABLE aid_requests ADD CONSTRAINT ck_aid_requests_reservation_allowed_state CHECK ( reservation_id IS NULL OR status IN ( 'RESERVED', 'DISPATCHED', 'DELIVERED', 'COMPLETED', 'CANCELLED' ) ),
ADD CONSTRAINT ck_aid_requests_reservation_required_state CHECK ( status NOT IN ( 'RESERVED', 'DISPATCHED', 'DELIVERED', 'COMPLETED' ) OR reservation_id IS NOT NULL ),
ADD CONSTRAINT ck_aid_requests_reservation_outcome_exclusive CHECK ( reservation_id IS NULL OR reservation_failure_reason IS NULL );
